<template><div v-if="open" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4"><div class="w-full max-w-3xl max-h-[92vh] overflow-hidden border border-slate-200 bg-white"><div class="flex items-center justify-between border-b px-6 py-4"><h2 class="text-lg font-semibold">Edit bank financing</h2><button @click="close" class="border px-3 py-2">×</button></div><div v-if="loadingData" class="p-12 text-center">Loading…</div><form v-else @submit.prevent="submit" class="max-h-[calc(92vh-80px)] overflow-y-auto"><div class="grid gap-4 p-6 md:grid-cols-2"><Field v-for="f in textFields" :key="f" :label="label(f)"><input v-model="form[f]" class="input"/></Field><Field label="Loan term months"><input v-model.number="form.loan_term_months" type="number" min="1" class="input"/></Field><Field label="Loan status"><select v-model="form.loan_status" class="input"><option>pending</option><option>approved</option><option>rejected</option><option>active</option><option>completed</option><option>cancelled</option></select></Field><Field label="Approved at"><input v-model="form.approved_at" type="datetime-local" class="input"/></Field><Field label="First payment date"><input v-model="form.first_payment_date" type="date" class="input"/></Field><Field label="Application ID"><input v-model.number="form.application" type="number" min="1" class="input"/></Field></div><div v-if="error" class="mx-6 mb-4 border border-red-200 bg-red-50 p-3 text-sm text-red-700">{{error}}</div><div class="flex justify-end gap-3 border-t p-4"><button type="button" @click="close" class="border px-5 py-2.5">Cancel</button><button :disabled="saving" class="border border-primary bg-primary px-5 py-2.5 text-white">{{saving?'Saving…':'Save changes'}}</button></div></form></div></div></template>
<script>import OffplanField from "../offplan property/OffplanField.vue";const blank={bank_name:"",loan_account_number:"",loan_amount:"",interest_rate:"",loan_term_months:0,monthly_payment:"",loan_status:"pending",approved_at:"",first_payment_date:"",notes:"",application:0};export default{name:"EditOffplanBankFinancing",components:{Field:OffplanField},props:{open:Boolean,id:[String,Number]},data(){return{form:{...blank},loadingData:false,saving:false,error:"",textFields:["bank_name","loan_account_number","loan_amount","interest_rate","monthly_payment","notes"]}},watch:{open(v){if(v)this.load()}},methods:{close(){if(!this.saving)this.$emit("close")},async load(){if(!this.id)return;this.loadingData=true;try{const r=await this.$apiGetById("/get_offplan_bank_financing",this.id);this.form={...blank,...(r?.data?.data||r?.data||r?.financing||r)}}catch(e){this.error=e?.message||"Unable to load financing."}finally{this.loadingData=false}},async submit(){this.saving=true;this.error="";try{await this.$apiPatch("/update_offplan_bank_financing",this.id,{...this.form,loan_term_months:Number(this.form.loan_term_months),application:Number(this.form.application)});this.$emit("saved");this.close()}catch(e){this.error=e?.message||"Unable to update financing."}finally{this.saving=false}}}};</script><style scoped>.input{width:100%;border:1px solid #cbd5e1;padding:.625rem .75rem;outline:none;background:#fff;font-size:.875rem}</style>